import{_ as s,a0 as r,w as i,s as a,I as o,x as n,a1 as e,A as u,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse(`{"title":"沒錯，Linux是感染了木馬！但，這並非企鵝的末日。 | LCTT x X-CMD","titleTemplate":false,"description":"沒錯，Linux是感染了木馬！但，這並非企鵝的末日。 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"沒錯，Linux是感染了木馬！但，這並非企鵝的末日。 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"沒錯，Linux是感染了木馬！但，這並非企鵝的末日。 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141211 Yes, This Trojan Infects Linux. No, It' s Not The Tuxpocalypse","title":"沒錯，Linux是感染了木馬！但，這並非企鵝的末日。","tag":"201501","desc":""},"relativePath":"201501/20141211 Yes, This Trojan Infects Linux. No, It' s Not The Tuxpocalypse.md","filePath":"[post].md"}`),T={name:"201501/20141211 Yes, This Trojan Infects Linux. No, It' s Not The Tuxpocalypse.md"};function x(d,t,m,g,f,L){const p=r("Link");return i(),a("div",null,[t[22]||(t[22]=o("h1",{id:"沒錯-linux是感染了木馬-但-這並非企鵝的末日。",tabindex:"-1"},[n("沒錯，Linux是感染了木馬！但，這並非企鵝的末日。 "),o("a",{class:"header-anchor",href:"#沒錯-linux是感染了木馬-但-這並非企鵝的末日。","aria-label":"Permalink to “沒錯，Linux是感染了木馬！但，這並非企鵝的末日。”"},"​")],-1)),t[23]||(t[23]=o("p",null,[o("img",{src:"http://www.omgubuntu.co.uk/wp-content/uploads/2014/12/spyware.jpg",alt:"Is something watching you?"})],-1)),t[24]||(t[24]=o("p",null,"譯註：原文標題中Tuxpocalypse是作者造的詞，由Tux和apocalypse組合而來。Tux是Linux的LOGO中那隻企鵝的名字，apocalypse意為末世、大災變，這裏翻譯成企鵝的末日。",-1)),t[25]||(t[25]=o("p",null,"你被監視了嗎？",-1)),o("p",null,[t[1]||(t[1]=n("帶上一箱罐頭，挖一個深坑碉堡，準備進入一個完全不同的新世界吧：",-1)),e(p,{href:"https://securelist.com/blog/research/67962/the-penquin-turla-2/"},{default:u(()=>[...t[0]||(t[0]=[n("一個強大的木馬已經在Linux中被發現",-1)])]),_:1}),t[2]||(t[2]=n("。",-1))]),t[26]||(t[26]=l('<p>沒錯，迄今為止最牢不可破的計算機世外桃源已經被攻破了，安全專家們都已成驚弓之鳥。</p><p>關掉電腦，拔掉鍵盤，然後再買只貓（忘掉YouTube吧）。企鵝末日已經降臨，我們的日子不多了。</p><p>我去？這是真的嗎？依我看，不一定吧~</p><h3 id="一次可怕的異常事件" tabindex="-1">一次可怕的異常事件！ <a class="header-anchor" href="#一次可怕的異常事件" aria-label="Permalink to “一次可怕的異常事件！”">​</a></h3><p>先聲明，<strong>我並沒有刻意輕視此次威脅（人們給這個木馬起名為‘Turla’）的嚴重性</strong>，為了避免質疑，我要強調的是，作為Linux用户，我們不應該為此次事件過分擔心。</p><p>此次發現的木馬能夠在人們毫無察覺的情況下感染Linux系統，這是非常可怕的。事實上，它的主要工作是搜尋並向外發送各種類型的敏感信息，這一點同樣令人感到恐懼。據瞭解，它已經存在至少4年時間，而且無需root權限就能完成這些工作。呃，這是要把人嚇尿的節奏嗎？</p><p>But - 但是 - 新聞稿裏常常這個時候該出現‘but’了 - 要説恐慌正在橫掃桌面Linux的粉絲，那就有點斷章取義、甚至不着邊際了。</p><p>對我們中的有些人來説，計算機安全隱患的確是一種新鮮事物，然而我們應該對其審慎對待：對桌面用户來説，Linux仍然是一個天生安全的操作系統。一次瑕疵不應該否定它的一切，我們沒有必要慌忙地割斷網線。</p><h3 id="國家資助-目標政府" tabindex="-1">國家資助，目標政府 <a class="header-anchor" href="#國家資助-目標政府" aria-label="Permalink to “國家資助，目標政府”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/12/penguin-snakle-by-icao-292x300.jpg" alt="Is a penguin snake a ‘Penguake’ or a ‘Snaguin’?"></p><p>企鵝和蛇的組合該叫‘企蛇’還是‘蛇鵝’？</p>',11)),o("p",null,[t[4]||(t[4]=n("‘Turla’木馬是一個複雜、高級的持續威脅，四年多來，它以政府、大使館以及製藥公司的系統為目標，其使用的攻擊方式所基於的代碼",-1)),e(p,{href:"https://twitter.com/joernchen/status/542060412188262400"},{default:u(()=>[...t[3]||(t[3]=[n("至少在14年前",-1)])]),_:1}),t[5]||(t[5]=n("就已存在了。",-1))]),t[27]||(t[27]=l('<p>在Windows系統中，安全研究領域來自賽門鐵克和卡巴斯基實驗室的超級英雄們首先發現了這條黏黏的蛇，他們發現Turla及其組件已經<strong>感染了45個國家的數百台個人電腦</strong>，其中許多都是通過未打補丁的0day漏洞感染的。</p><p><em>微軟，幹得漂亮。</em></p><p>經過卡巴斯基實驗室的進一步努力，他們發現，同樣的木馬出現在了Linux上。</p><p>這款木馬無需高權限就可以“攔截傳入的數據包，在系統中執行傳入的命令”，但是它的觸角到底有多深，有多少Linux系統被感染，它的完整功能都有哪些，這些目前都暫時還不明朗。</p><p>根據它選定的目標，我們推斷“Turla”（及其變種）是由某些民族的國家資助的。美國和英國的讀者不要想當然以為這些國家就是“那些國家”。不要忘了我們自己的政府也很樂於趟這攤渾水。</p><h4 id="觀點-與-責任" tabindex="-1">觀點 與 責任 <a class="header-anchor" href="#觀點-與-責任" aria-label="Permalink to “觀點 與 責任”">​</a></h4><p>這次的發現從情感上、技術上、倫理上，都是一次嚴重的失利，但它遠沒有達到説我們已經進入一個病毒和惡意軟件針對桌面自由肆虐的時代。</p><p><strong>Turla 並不是那種用户關注的“我想要你的信用卡”病毒</strong>，那些病毒往往綁定在一個偽造的軟件下載鏈接中。Turla是一種複雜的、經過巧妙處理的、具有高度適應性的威脅，它時刻都具有着特定的目標（因此它絕不僅僅滿足於蒐集一些賣萌少女的網站賬户密碼，sorry 綠茶婊們！）。</p><p>卡巴斯基實驗室是這樣介紹的：</p><blockquote><p>“Linux上的Turla模組是一個鏈接多個靜態庫的C/C++可執行文件，這大大增加了它的文件體積。但它並沒有着重減小自身的文件體積，而是剝離了自身的符號信息，這樣就增加了對它逆向分析的難度。它的功能主要包括隱藏網絡通信、遠程執行任意命令以及遠程管理等等。它的大部分代碼都基於公開源碼。”</p></blockquote><p>不管它的影響和感染率如何，它的技術優勢都將不斷給那些號稱聰明的專家們留下一個又一個問題，就讓他們花費大把時間去追蹤、分析、解決這些問題吧。</p><p>我不是一個計算機安全專家，但我是一個理智的網絡腦殘粉，要我説，這次事件應該被看做是一個通（jing）報（gao），而並非有些網站所標榜的洪（shi）水（jie）猛（mo）獸（ri）。</p><p>在更多細節披露之前，我們都不必恐慌。只需繼續計算機領域的安全實踐，避免從不信任的網站或PPA源下載運行腳本、app或二進制文件，更不要冒險進入web網絡的黑暗領域。</p>',13)),o("p",null,[t[7]||(t[7]=n("如果你仍然十分擔心，你可以前往",-1)),e(p,{href:"https://securelist.com/blog/research/67962/the-penquin-turla-2/"},{default:u(()=>[...t[6]||(t[6]=[n("卡巴斯基的Blog",-1)])]),_:1}),t[8]||(t[8]=n("查看更多細節，以確定自己是否感染。",-1))]),t[28]||(t[28]=o("hr",null,null,-1)),o("p",null,[t[10]||(t[10]=n("via: ",-1)),e(p,{href:"http://www.omgubuntu.co.uk/2014/12/government-spying-turla-linux-trojan-found"},{default:u(()=>[...t[9]||(t[9]=[n("http://www.omgubuntu.co.uk/2014/12/government-spying-turla-linux-trojan-found",-1)])]),_:1})]),o("p",null,[t[14]||(t[14]=n("作者：",-1)),e(p,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:u(()=>[...t[11]||(t[11]=[n("Joey-Elijah Sneddon",-1)])]),_:1}),t[15]||(t[15]=n(" 譯者：",-1)),e(p,{href:"http://blog.csdn.net/tinyeyeser"},{default:u(()=>[...t[12]||(t[12]=[n("Mr小眼兒",-1)])]),_:1}),t[16]||(t[16]=n(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:u(()=>[...t[13]||(t[13]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[19]||(t[19]=n("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[17]||(t[17]=[n("LCTT",-1)])]),_:1}),t[20]||(t[20]=n(" 原創翻譯，",-1)),e(p,{href:"http://linux.cn/"},{default:u(()=>[...t[18]||(t[18]=[n("Linux中國",-1)])]),_:1}),t[21]||(t[21]=n(" 榮譽推出",-1))])])}const y=s(T,[["render",x]]);export{C as __pageData,y as default};
